//! Experimental routes: only registered, fd-anchored external workspaces reach these handlers.
use std::{sync::{Arc,Mutex},io::{self,Read}};use serde_json::{json,Value};use tiny_http::Request;
use crate::{workspace_worker::Workers,semantic::SemanticService};
type States=Arc<Mutex<std::collections::HashMap<String,String>>>;
fn send(workers:&Workers,id:&str,request:Value)->Result<Value,String>{let result=workers.request(id,&request).map_err(|_|"Внешнее пространство недоступно".to_owned())?;if let Some(error)=result["error"].as_str(){return Err(error.to_owned())}result.get("ok").cloned().ok_or("Некорректный ответ пространства".to_owned())}
fn send_session(workers:&Workers,id:&str,session:&str,request:Value)->Result<Value,String>{let result=workers.request_session(id,session,&request).map_err(|e|if e.to_string().contains("timeout"){"Пространство не отвечает. Результат операции не подтверждён; проверьте данные после повторного подключения.".to_owned()}else{"Пространство отключено. Результат операции не подтверждён; проверьте данные после повторного подключения.".to_owned()})?;if let Some(error)=result["error"].as_str(){return Err(error.to_owned())}result.get("ok").cloned().ok_or("Некорректный ответ пространства".to_owned())}
fn enqueue(workers:Arc<Workers>,states:States,id:String,semantic:Option<SemanticService>){let Some(semantic)=semantic else{return};{let Ok(mut states)=states.lock()else{return};if states.get(&id).is_some_and(|s|s=="indexing"){states.insert(id,"dirty".into());return}states.insert(id.clone(),"indexing".into());}let Ok(session)=workers.session(&id)else{return};std::thread::spawn(move||{loop{let result=crate::worker_models::rebuild_session(&workers,&id,&session,&semantic);if workers.session(&id).ok().as_deref()!=Some(session.as_str()){break}let Ok(mut states)=states.lock()else{break};if !states.contains_key(&id){break}if states.get(&id).is_some_and(|s|s=="dirty"){states.insert(id.clone(),"indexing".into());continue}states.insert(id.clone(),if result.is_ok(){"ready".into()}else{"failed".into()});break}});}
pub fn attach(root:&std::path::Path,workers:Arc<Workers>,states:States,mut req:Request,semantic:Option<SemanticService>){#[cfg(any(feature="test-hook",feature="protected-external"))] let mut retry_capability:Option<String>=None;let result=(||->Result<Value,String>{let b=super::body(&mut req).map_err(|_|"Некорректный запрос")?;let (mut selected,mut dir)=crate::capability::consume("attach",b["capability"].as_str().unwrap_or(""))?;if selected.starts_with(root.canonicalize().map_err(|_|"Некорректный реестр")?){return Err("Это пространство уже хранится внутри Atlas".into())}#[cfg(any(feature="test-hook",feature="protected-external"))] if b["test_protected"]==true {
 if !crate::protected::Protected::is_protected_dir(&selected){return Err("Не найдено защищённое пространство".into())}
 let password=b["password"].as_str().filter(|s|!s.is_empty()).ok_or("Укажите пароль")?;
 let id=if let Some(id)=b["id"].as_str(){if !crate::external_registry::entries(root).map_err(|e|e.to_string())?.iter().any(|entry|entry["id"]==id&&entry["protected"]==true){return Err("Неизвестное защищённое пространство".into())}id.to_owned()}else{uuid::Uuid::new_v4().simple().to_string()};
 workers.attach_protected_for_test(&id,&dir,&selected).map_err(|_|"Не удалось открыть пространство")?;
 if let Err(error)=send(&workers,&id,json!({"action":"unlock","password":password})){let _=workers.detach(&id);retry_capability=crate::capability::reissue_attach(&selected,&dir).ok();return Err(error)}
 let info=match send(&workers,&id,json!({"action":"workspace-info"})){Ok(value)=>value,Err(error)=>{let _=workers.detach(&id);return Err(error)}};
 let registered=(||->Result<(),String>{let name=info["name"].as_str().ok_or("Некорректное имя")?;let identity=info["identity"].as_str().ok_or("Некорректная метка")?;crate::external_registry::register_protected(root,&id,name,identity).map_err(|e|e.to_string())})();if let Err(error)=registered{let _=workers.detach(&id);return Err(error)}
 if let Err(e)=crate::external_registry::remember_path(root,&id,&selected){let _=workers.detach(&id);return Err(e.to_string())}
 if let Ok(mut state)=states.lock(){state.insert(id.clone(),"loading".into());}
 return Ok(json!({"id":id,"name":info["name"],"external":true,"protected":true,"available":true}));
 }if !super::valid_workspace(&selected) {use std::os::{fd::{AsRawFd,FromRawFd},unix::{ffi::OsStrExt,fs::MetadataExt}};let pinned=dir.metadata().map_err(|_|"Папка недоступна")?;let current=std::fs::symlink_metadata(&selected).map_err(|_|"Папка недоступна")?;if current.file_type().is_symlink()||(pinned.dev(),pinned.ino())!=(current.dev(),current.ino()){return Err("Выбранная папка изменилась; выберите её заново".into())}let mut candidates=Vec::new();for entry in std::fs::read_dir(&selected).map_err(|_|"Не удалось прочитать папку")? {let entry=entry.map_err(|_|"Не удалось прочитать папку")?;let ty=entry.file_type().map_err(|_|"Не удалось проверить папку")?;if ty.is_dir()&&!ty.is_symlink()&&super::valid_workspace(&entry.path()){candidates.push(entry.path());}}if candidates.len()!=1{return Err("Выберите папку конкретного пространства Atlas; в выбранной папке их нет или их несколько".into())}selected=candidates.pop().unwrap();let name=std::ffi::CString::new(selected.file_name().ok_or("Некорректная папка")?.as_bytes()).map_err(|_|"Некорректная папка")?;let fd=unsafe{libc::openat(dir.as_raw_fd(),name.as_ptr(),libc::O_RDONLY|libc::O_DIRECTORY|libc::O_NOFOLLOW|libc::O_CLOEXEC)};if fd<0{return Err("Не удалось открыть пространство".into())}let child=unsafe{std::fs::File::from_raw_fd(fd)};let opened=child.metadata().map_err(|_|"Пространство недоступно")?;let current=std::fs::symlink_metadata(&selected).map_err(|_|"Пространство недоступно")?;if current.file_type().is_symlink()||(opened.dev(),opened.ino())!=(current.dev(),current.ino()){return Err("Папка пространства изменилась; выберите её заново".into())}dir=child;}if selected.starts_with(root.canonicalize().map_err(|_|"Некорректный реестр")?){return Err("Это пространство уже хранится внутри Atlas".into())}let id=if let Some(id)=b["id"].as_str(){if !crate::external_registry::entries(root).map_err(|e|e.to_string())?.iter().any(|entry|entry["id"]==id){return Err("Неизвестное пространство".into())}id.to_owned()}else{uuid::Uuid::new_v4().simple().to_string()};workers.attach(&id,&dir,&selected).map_err(|_|"Не удалось открыть пространство: проверьте папку, доступ к носителю и не открыто ли оно в другом Atlas".to_owned())?;let info=match send(&workers,&id,json!({"action":"workspace-info"})){Ok(v)=>v,Err(e)=>{let _=workers.detach(&id);return Err(e)}};let register=crate::external_registry::register(root,&id,info["name"].as_str().ok_or("Некорректное имя")?,info["identity"].as_str().ok_or("Некорректная метка")?);if let Err(e)=register{let _=workers.detach(&id);return Err(e.to_string())}if let Err(e)=crate::external_registry::remember_path(root,&id,&selected){let _=workers.detach(&id);return Err(e.to_string())}if let Ok(mut s)=states.lock(){s.insert(id.clone(),"loading".into());}Ok(json!({"id":id,"name":info["name"],"external":true,"available":true}))})();match result{Ok(v)=>super::answer(req,200,v),Err(e)=>{
 #[cfg(any(feature="test-hook",feature="protected-external"))]
 if let Some(token)=retry_capability {return super::answer(req,403,json!({"error":e,"retry_capability":token}))}
 let code=if matches!(e.as_str(),"Выбрано другое пространство"|"Не найдено защищённое пространство"){"path_changed"}else{"attach_failed"};super::answer(req,400,json!({"error":e,"code":code}))}}}
pub fn rename(root:&std::path::Path,workers:&Workers,mut req:Request,id:&str){let result=(||->Result<Value,String>{let b=super::body(&mut req).map_err(|_|"Некорректный запрос")?;let session=workers.session(id).map_err(|_|"Пространство отключено")?;let renamed=send_session(workers,id,&session,json!({"action":"workspace-rename","name":b["name"]}))?;let info=send_session(workers,id,&session,json!({"action":"workspace-info"}))?;crate::external_registry::register(root,id,renamed["name"].as_str().ok_or("Некорректное имя")?,info["identity"].as_str().ok_or("Некорректная метка")?).map_err(|_|"Название изменено в папке, но не удалось обновить список. Откройте пространство заново.")?;Ok(json!({"id":id,"name":renamed["name"],"external":true,"available":true}))})();match result{Ok(value)=>super::answer(req,200,value),Err(error)=>super::answer(req,409,json!({"error":error}))}}
pub fn close(workers:&Workers,states:&States,req:Request,id:&str){let result=workers.detach(id);if let Ok(mut s)=states.lock(){s.remove(id);}match result{Ok(())=>super::answer(req,200,json!({"ok":true})),Err(_)=>super::answer(req,404,json!({"error":"Пространство недоступно"}))}}
struct DownloadReader {workers:Arc<Workers>,id:String,session:String,stream:String,buffer:Vec<u8>,pos:usize,done:bool}
impl Read for DownloadReader {fn read(&mut self,out:&mut[u8])->io::Result<usize>{if out.is_empty(){return Ok(0)}if self.pos==self.buffer.len()&&!self.done{let value=send_session(&self.workers,&self.id,&self.session,json!({"action":"download-next","stream":self.stream})).map_err(io::Error::other)?;let list=value["bytes"].as_array().ok_or_else(||io::Error::other("invalid bytes"))?;self.buffer=list.iter().map(|b|b.as_u64().filter(|n|*n<=255).map(|n|n as u8).ok_or_else(||io::Error::other("invalid byte"))).collect::<Result<Vec<_>,_>>()?;self.pos=0;self.done=value["done"].as_bool().ok_or_else(||io::Error::other("invalid download"))?;if self.buffer.is_empty()&&!self.done{return Err(io::Error::other("empty download"))}}let n=out.len().min(self.buffer.len()-self.pos);out[..n].copy_from_slice(&self.buffer[self.pos..self.pos+n]);self.pos+=n;Ok(n)}}
impl Drop for DownloadReader{fn drop(&mut self){if !self.done{let _=send_session(&self.workers,&self.id,&self.session,json!({"action":"download-cancel","stream":self.stream}));}}}
pub fn handle(root:&std::path::Path,default:&std::path::Path,serial:&Mutex<()>,workers:Arc<Workers>,states:States,mut req:Request,id:String,resource:Vec<String>,semantic:Option<SemanticService>,rag:Arc<Mutex<crate::RagState>>,choice:Arc<crate::ModelChoice>){let session=match workers.session(&id){Ok(v)=>v,Err(_)=>return super::answer(req,409,json!({"error":"Пространство отключено"}))};let method=req.method().as_str().to_owned();let route:Vec<&str>=resource.iter().map(String::as_str).collect();
 if method=="POST"&&route.as_slice()==["files","copy"]{let result=(||->Result<Value,String>{let b=super::body(&mut req).map_err(|_|"Некорректный запрос")?;let source=b["source_workspace"].as_str().ok_or("Некорректный источник")?;if source!="default"&&(source.len()!=32||!source.chars().all(|c|c.is_ascii_hexdigit())){return Err("Некорректный источник".into())}let resolved=crate::workspace_paths::resolve(root,default,source);if crate::protected::Protected::is_protected(root,default,source)||crate::protected::Protected::is_protected_dir(&resolved){return Err("Копирование из защищённого пространства пока недоступно".into())}let object=b["source_id"].as_str().ok_or("Некорректный объект")?;let revision=b["expected_revision"].as_str().ok_or("Некорректная ревизия")?;let _serial=serial.lock().map_err(|_|"Сервер недоступен")?;let _reservation=crate::portable_worker::reserve(vec![source.to_owned(),id.clone()]).map_err(|_|"Идёт копирование пространства")?;let path=if workers.contains(source){None}else{if crate::external_registry::entries(root).map_err(|e|e.to_string())?.iter().any(|entry|entry["id"]==source){return Err("Подключите исходное пространство".into())}let path=crate::workspace_paths::resolve(root,default,source);if !super::valid_workspace(&path){return Err("Исходное пространство недоступно".into())}Some(path)};drop(_serial);crate::external_copy::copy(workers.clone(),source,path,&id,None,object,revision)})();return match result{Ok(value)=>{enqueue(workers,states,id,semantic);super::answer(req,201,value)},Err(error)=>super::answer(req,409,json!({"error":error}))}}

 if method=="GET"&&matches!(route.as_slice(),["files",_,"content"]){let oid=route[1];let value=match send_session(&workers,&id,&session,json!({"action":"download-begin","id":oid})){Ok(v)=>v,Err(_)=>return super::answer(req,404,json!({"error":"Файл недоступен"}))};let Some(title)=value["title"].as_str()else{return super::answer(req,500,json!({"error":"Файл недоступен"}))};let Some(size)=value["size"].as_u64().and_then(|x|usize::try_from(x).ok())else{return super::answer(req,500,json!({"error":"Файл недоступен"}))};let (mime,safe)=super::mime(title);let encoded=percent_encoding::utf8_percent_encode(title,percent_encoding::NON_ALPHANUMERIC).to_string();let mut headers=vec![tiny_http::Header::from_bytes("Content-Type",mime).unwrap(),tiny_http::Header::from_bytes("Content-Disposition",format!("{}; filename*=UTF-8''{}",if safe{"inline"}else{"attachment"},encoded)).unwrap(),tiny_http::Header::from_bytes("X-Content-Type-Options","nosniff").unwrap(),tiny_http::Header::from_bytes("Content-Security-Policy","sandbox; default-src 'none'").unwrap()];let Some(stream)=value["stream"].as_str().map(str::to_owned) else{return super::answer(req,500,json!({"error":"Файл недоступен"}))};let reader=DownloadReader{workers,id,session,stream,buffer:vec![],pos:0,done:false};let _=req.respond(tiny_http::Response::new(tiny_http::StatusCode(200),std::mem::take(&mut headers),reader,Some(size),None));return}
 if (method=="POST"&&route.as_slice()==["files"])||(method=="PUT"&&matches!(route.as_slice(),["files",_])){if req.headers().iter().find(|h|h.field.equiv("Content-Type")).map(|h|h.value.as_str())!=Some("application/octet-stream"){return super::answer(req,400,json!({"error":"Некорректный тип файла"}))}let size=match req.body_length(){Some(n) if n<=10usize*1024*1024*1024=>n as u64,_=>return super::answer(req,400,json!({"error":"Некорректный размер"}))};let query=req.url().split_once('?').map(|x|x.1).unwrap_or("");let names:Vec<String>=url::form_urlencoded::parse(query.as_bytes()).filter(|(k,_)|k=="filename").map(|(_,v)|v.into_owned()).collect();if names.len()!=1{return super::answer(req,400,json!({"error":"Некорректное имя файла"}))}let object_id=if method=="PUT"{Some(route[1])}else{None};let mut stream=None;let result=(||->Result<Value,String>{let started=send_session(&workers,&id,&session,json!({"action":"upload-begin","name":names[0],"size":size,"id":object_id}))?;stream=Some(started["stream"].as_str().ok_or("Ошибка загрузки")?.to_owned());let mut remaining=size;let mut buf=[0u8;65536];while remaining>0{let length=buf.len().min(remaining as usize);let n=req.as_reader().read(&mut buf[..length]).map_err(|_|"Ошибка загрузки".to_string())?;if n==0{return Err("Загрузка прервана".into())}send_session(&workers,&id,&session,json!({"action":"upload-chunk","stream":stream,"bytes":&buf[..n]}))?;remaining-=n as u64;}let uploaded=send_session(&workers,&id,&session,json!({"action":"upload-finish","stream":stream}))?;let board=send_session(&workers,&id,&session,json!({"action":"get-board","args":[]}))?;let mut obj=board["objects"].as_array().and_then(|v|v.iter().find(|x|x["id"]==uploaded["id"])).cloned().ok_or("Файл недоступен")?;if method=="POST"{let revision=send_session(&workers,&id,&session,json!({"action":"object-revision","id":uploaded["id"]}))?;obj["revision"]=revision["revision"].clone()}Ok(obj)})();return match result{Ok(v)=>{enqueue(workers,states,id,semantic);super::answer(req,200,v)},Err(e)=>{let _=send_session(&workers,&id,&session,json!({"action":"upload-cancel","stream":stream}));super::answer(req,400,json!({"error":e}))}}}
 let mut changed=false;let run=(||->Result<(u16,Value),String>{let body=if matches!(method.as_str(),"POST"|"PUT"|"PATCH"){Some(super::body(&mut req).map_err(|_|"Некорректный запрос")?)}else{None};let b=body.as_ref().unwrap_or(&Value::Null);let r:Vec<&str>=resource.iter().map(String::as_str).collect();
 let result=match (method.as_str(),r.as_slice()){
 ("GET",["board"])=>send_session(&workers,&id,&session,json!({"action":"get-board","args":[]}))?,
 ("PUT",["board"])=>{changed=true;send_session(&workers,&id,&session,json!({"action":"put-board","args":[b.to_string()]}))?;send_session(&workers,&id,&session,json!({"action":"get-board","args":[]}))?},
 ("POST",["notes"])=>{changed=true;let created=send_session(&workers,&id,&session,json!({"action":"create-note","args":[b["title"],b["text"]]}))?;let nid=created["id"].as_str().ok_or("Некорректный ответ")?;let revision=send_session(&workers,&id,&session,json!({"action":"object-revision","id":nid}))?;return Ok((201,json!({"id":nid,"title":b["title"],"kind":"note","x":0,"y":0,"revision":revision["revision"]})))},
 ("GET",["notes",nid])=>send_session(&workers,&id,&session,json!({"action":"get-note","args":[nid]}))?,
 ("PUT",["notes",nid])=>{changed=true;send_session(&workers,&id,&session,json!({"action":"update-note","args":[nid,b["title"],b["text"]]}))?;send_session(&workers,&id,&session,json!({"action":"get-note","args":[nid]}))?},
 ("GET",["objects",oid,"revision"])=>send_session(&workers,&id,&session,json!({"action":"file-revision","id":oid}))?,
 ("POST",["objects",oid,"undo-create"])=>{changed=true;send_session(&workers,&id,&session,json!({"action":"undo-created","id":oid,"expected_revision":b["expected_revision"]}))?;json!({"ok":true})},
 ("GET",["objects",oid,"description"])=>send_session(&workers,&id,&session,json!({"action":"get-description","id":oid}))?,
 ("PUT",["objects",oid,"description"])=>{changed=true;send_session(&workers,&id,&session,json!({"action":"set-description","id":oid,"description":b["description"]}))?},
 ("GET",["objects",oid,"search-text"])=>send_session(&workers,&id,&session,json!({"action":"search-text","id":oid}))?,
 ("POST",["trash",oid,"restore"])=>{changed=true;let board=send_session(&workers,&id,&session,json!({"action":"restore-objects","ids":[oid]}))?;board["objects"].as_array().and_then(|items|items.iter().find(|item|item["id"]==*oid)).cloned().ok_or("Объект недоступен")?},
 ("GET",["history"])=>send_session(&workers,&id,&session,json!({"action":"history"}))?,
 ("GET",["trash"])=>json!({"objects":send_session(&workers,&id,&session,json!({"action":"list-trash","args":[]}))?}),
 ("DELETE",["objects",oid])=>{changed=true;send_session(&workers,&id,&session,json!({"action":"delete-objects","ids":[oid]}))?;json!({"ok":true})},
 ("POST",["objects","delete-many"])=>{changed=true;send_session(&workers,&id,&session,json!({"action":"delete-objects","ids":b["ids"]}))?},
 ("POST",["trash","restore-many"])=>{changed=true;send_session(&workers,&id,&session,json!({"action":"restore-objects","ids":b["ids"]}))?},
 ("GET",["rag","status"])=>{let state=rag.lock().map_err(|_|"Модель недоступна")?;let name=choice.selected.lock().map_err(|_|"Модель недоступна")?.clone();let mut result=match &*state{crate::RagState::Ready(_)=>json!({"available":true,"message":""}),crate::RagState::Loading=>json!({"available":false,"message":"Загрузка модели ответа"}),_=>json!({"available":false,"message":"Модель ответа не загружена"})};result["model"]=json!(name);result["warning"]=json!(choice.warning.lock().ok().and_then(|v|v.clone()));result["installed_e2b"]=json!(choice.dir.join("gemma-4-e2b-it-q4.gguf").is_file());result["installed_e4b"]=json!(choice.dir.join("gemma-4-e4b-it-q4.gguf").is_file());result},
 ("POST",["rag","search"])=>{let index_state=states.lock().map_err(|_|"Состояние недоступно")?.get(&id).cloned();if index_state.as_deref().is_none_or(|s|matches!(s,"loading"|"indexing"|"dirty")) {if index_state.as_deref().is_none_or(|s|s=="loading"){enqueue(workers.clone(),states.clone(),id.clone(),semantic.clone());}return Ok((503,json!({"error":"Подготавливаем индекс поиска. Попробуйте ещё раз через несколько секунд."})))}let model=semantic.as_ref().ok_or("Модель не загружена")?;crate::external_rag::search(&workers,&id,&session,model,&rag,b)?},
 ("GET",["semantic","status"])=>{let state=states.lock().map_err(|_|"Состояние недоступно")?.get(&id).cloned().unwrap_or_default();json!({"available":semantic.is_some()&&(state=="ready"||state=="loading"||state.is_empty()),"message":match state.as_str(){"ready"=>"","loading"=>"Загрузка модели","indexing"|"dirty"=>"Идёт обработка",_=>"Поиск по смыслу недоступен"},"processing_ids":[],"failed_ids":[]})},
 ("POST",["semantic","rebuild"])=>{enqueue(workers.clone(),states.clone(),id.clone(),semantic.clone());return Ok((202,json!({"ok":true})))},
 ("POST",["search"]) if b["mode"]=="lexical"=>{let result=send_session(&workers,&id,&session,json!({"action":"lexical-search","query":b["query"],"ids":b["object_ids"]}))?;if b["query"].as_str().is_some_and(|q|!q.trim().is_empty())&&result["revision"].is_string(){send_session(&workers,&id,&session,json!({"action":"history-save","query":b["query"],"mode":"lexical","object_ids":b["object_ids"],"results":result["results"],"revision":result["revision"]}))?;}json!({"results":result["results"],"error":if result["revision"].is_null(){Some("Результаты найдены, но историю сохранить не удалось: слишком большой документ или ошибка чтения.")}else{None}})},
 ("POST",["search"]) if b["mode"]=="semantic"=>{let index_state=states.lock().map_err(|_|"Состояние недоступно")?.get(&id).cloned();if index_state.as_deref().is_none_or(|s|matches!(s,"loading"|"indexing"|"dirty")) {if index_state.as_deref().is_none_or(|s|s=="loading"){enqueue(workers.clone(),states.clone(),id.clone(),semantic.clone());}return Ok((503,json!({"error":"Подготавливаем индекс поиска. Попробуйте ещё раз через несколько секунд."})))}let model=semantic.as_ref().ok_or("Модель не загружена")?;let result=crate::worker_models::search_session(&workers,&id,&session,model,b["query"].as_str().ok_or("Некорректный запрос")?,match b.get("object_ids"){None|Some(Value::Null)=>None,Some(Value::Array(ids))=>Some(ids.iter().map(|x|x.as_str().map(str::to_owned).ok_or("Некорректный фильтр")).collect::<Result<Vec<_>,_>>()?),_=>return Err("Некорректный фильтр".into())}.as_deref()).map_err(|e|e.to_string())?;if b["query"].as_str().is_some_and(|q|!q.trim().is_empty()){send_session(&workers,&id,&session,json!({"action":"history-save","query":b["query"],"mode":"semantic","object_ids":b["object_ids"],"results":result["results"],"revision":result["revision"]}))?;}json!({"results":result["results"]})},
 _=>return Ok((501,json!({"error":"Операция для внешнего пространства пока не поддерживается"}))) };Ok((200,result))})();if changed&&run.is_ok(){enqueue(workers,states,id,semantic)}match run{Ok((status,v))=>super::answer(req,status,v),Err(e)=>super::answer(req,409,json!({"error":e}))}}
pub struct ExportPause {workers:Arc<Workers>,states:States,semantic:Option<SemanticService>,entries:Vec<(String,String)>,#[cfg(any(feature="test-hook",feature="protected-external"))] protected_entries:Vec<(String,String,String)>}
impl ExportPause {pub fn new(workers:Arc<Workers>,states:States,semantic:Option<SemanticService>)->Self{Self{workers,states,semantic,entries:Vec::new(),#[cfg(any(feature="test-hook",feature="protected-external"))] protected_entries:Vec::new()}}pub fn pause(&mut self,id:&str,session:&str)->Result<(),String>{send_session(&self.workers,id,session,json!({"action":"export-prepare"}))?;self.entries.push((id.to_owned(),session.to_owned()));Ok(())}
#[cfg(any(feature="test-hook",feature="protected-external"))] pub fn pause_protected(&mut self,id:&str,session:&str,password:&str)->Result<(),String>{send_session(&self.workers,id,session,json!({"action":"export-prepare","password":password}))?;self.protected_entries.push((id.to_owned(),session.to_owned(),password.to_owned()));Ok(())}
#[cfg(any(feature="test-hook",feature="protected-external"))] pub fn check_protected(&self)->Result<(),String>{for(id,session,_)in &self.protected_entries{send_session(&self.workers,id,session,json!({"action":"export-check"}))?;}Ok(())}
#[cfg(any(feature="test-hook",feature="protected-external"))] pub fn resume_protected(&mut self)->Result<(),String>{let mut errors=Vec::new();for(id,session,password)in self.protected_entries.drain(..){if let Err(error)=send_session(&self.workers,&id,&session,json!({"action":"export-resume","password":password})){errors.push(format!("{id}: {error}"));}else{enqueue(self.workers.clone(),self.states.clone(),id,self.semantic.clone());}}if errors.is_empty(){Ok(())}else{Err(errors.join("; "))}}
}
impl Drop for ExportPause {fn drop(&mut self){#[cfg(any(feature="test-hook",feature="protected-external"))] let _=self.resume_protected();for(id,session)in self.entries.drain(..){if send_session(&self.workers,&id,&session,json!({"action":"export-resume"})).is_ok(){enqueue(self.workers.clone(),self.states.clone(),id,self.semantic.clone());}}}}
#[cfg(any(feature="test-hook",feature="protected-external"))]
pub fn inspect_attach(root:&std::path::Path,mut req:Request){
 let result=(||->Result<Value,String>{let body=super::body(&mut req).map_err(|_|"Некорректный запрос")?;let(mut path,mut dir)=crate::capability::consume("attach",body["capability"].as_str().unwrap_or(""))?;
 if !crate::protected::Protected::is_protected_dir(&path)&&!super::valid_workspace(&path){
  use std::os::{fd::{AsRawFd,FromRawFd},unix::{ffi::OsStrExt,fs::MetadataExt}};
  let pinned=dir.metadata().map_err(|_|"Папка недоступна")?;let current=std::fs::symlink_metadata(&path).map_err(|_|"Папка недоступна")?;
  if current.file_type().is_symlink()||(pinned.dev(),pinned.ino())!=(current.dev(),current.ino()){return Err("Выбранная папка изменилась".into())}
  let mut candidates=Vec::new();for entry in std::fs::read_dir(&path).map_err(|_|"Не удалось прочитать папку")? {let entry=entry.map_err(|_|"Не удалось прочитать папку")?;let ty=entry.file_type().map_err(|_|"Не удалось проверить папку")?;if ty.is_dir()&&!ty.is_symlink()&&(super::valid_workspace(&entry.path())||crate::protected::Protected::is_protected_dir(&entry.path())){candidates.push(entry.path());}}
  if candidates.len()!=1{return Err("Выберите папку конкретного пространства Atlas".into())}let child_path=candidates.pop().unwrap();let name=std::ffi::CString::new(child_path.file_name().ok_or("Некорректная папка")?.as_bytes()).map_err(|_|"Некорректная папка")?;let fd=unsafe{libc::openat(dir.as_raw_fd(),name.as_ptr(),libc::O_RDONLY|libc::O_DIRECTORY|libc::O_NOFOLLOW|libc::O_CLOEXEC)};if fd<0{return Err("Не удалось открыть пространство".into())}let child=unsafe{std::fs::File::from_raw_fd(fd)};let opened=child.metadata().map_err(|_|"Пространство недоступно")?;let current=std::fs::symlink_metadata(&child_path).map_err(|_|"Пространство недоступно")?;if current.file_type().is_symlink()||(opened.dev(),opened.ino())!=(current.dev(),current.ino()){return Err("Папка пространства изменилась".into())}path=child_path;dir=child;
 }
 if path.starts_with(root.canonicalize().map_err(|_|"Некорректный реестр")?){return Err("Это пространство уже хранится внутри Atlas".into())}let is_protected=crate::protected::Protected::is_protected_dir(&path);let token=crate::capability::reissue_attach(&path,&dir)?;Ok(json!({"protected":is_protected,"capability":token}))})();
 match result{Ok(value)=>super::answer(req,200,value),Err(error)=>{let code=if matches!(error.as_str(),"Выберите папку конкретного пространства Atlas"|"Выбранная папка изменилась"|"Папка пространства изменилась"|"selection unavailable"|"selection changed"){"path_changed"}else{"inspection_failed"};super::answer(req,400,json!({"error":error,"code":code}))}}
}
